practice.solution:
-- The items table from the previous part
CREATE TABLE items (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name text UNIQUE
);

INSERT INTO items (name)
SELECT DISTINCT item
FROM orders_flat
ORDER BY item;

ALTER TABLE orders_flat ADD COLUMN item_id integer REFERENCES items (id);

UPDATE orders_flat AS o
SET item_id = i.id
FROM items AS i
WHERE i.name = o.item;

ALTER TABLE orders_flat DROP COLUMN item;

SELECT o.id, o.customer_name, i.name AS item, o.qty
FROM orders_flat AS o
JOIN items AS i ON i.id = o.item_id
ORDER BY o.id;

